-- Studio "TUMI Validation" (v3): 248 item TUMI + 6 bogus item validati
-- empiricamente (Curran & Hauser, 2019), randomizzati con seed per-partecipante
-- reversibile. Promosso da NexLudica APS. Responsabile: V. Guerrieri.
--
-- - 6 bogus items con FP ≤ 7% e FN ≤ 10% dalla Tabella 1 di Curran & Hauser
--   (sostituiti gli instructed-response che hanno FN 32-37%)
-- - Pre-shuffle build-time (seed 20260521) per bilanciare costrutti sulle pagine
-- - Client-side: nx_shuffle_across_pages = true → seed univoco per partecipante,
--   persistito in localStorage e salvato come _randomization_seed nel payload
-- - Consenso bloccante (validator + handler onCurrentPageChanging nel renderer)

INSERT OR REPLACE INTO research_studies
  (id, slug, title, description, status, public_listing,
   anonymous_code_template, identity_fields, theme_json,
   created_at, updated_at, created_by)
VALUES (
  '00000000-0000-4000-8000-300000000001',
  'tumi-validation',
  'TUMI Validation Study',
  'Studio di validazione internazionale del TUMI (Tabletop User Motivation Inventory), strumento psicometrico per misurare le motivazioni dei giocatori di giochi da tavolo. Promosso da NexLudica APS. Responsabile della ricerca: Vittorio Guerrieri. Tempo di compilazione: circa 20-25 minuti. Include item di controllo della disattenzione.',
  'active',
  1,
  '{anon_madre}{anon_giorno}{anon_nome}{anon_telefono}',
  'anon_madre,anon_giorno,anon_nome,anon_telefono',
  NULL,
  unixepoch()*1000,
  unixepoch()*1000,
  NULL
);

INSERT OR REPLACE INTO research_questionnaires
  (id, study_id, slug, title, description, schema_json,
   position, status, version, created_at, updated_at)
VALUES (
  '00000000-0000-4000-8000-300000000010',
  '00000000-0000-4000-8000-300000000001',
  'tumi',
  'TUMI — questionario completo',
  '254 item totali (248 TUMI + 6 bogus). Tempo stimato: 20-25 minuti.',
  '{"title":"TUMI Validation Study","description":"Tabletop User Motivation Inventory — validation study by NexLudica APS","showProgressBar":"top","progressBarType":"pages","showQuestionNumbers":"off","requiredText":"*","locale":"it","nx_shuffle_across_pages":true,"completedHtml":"<div style=\"padding:32px;text-align:center;\"><h2 style=\"color:#05abc4;\">Grazie!</h2><p>La tua partecipazione contribuisce alla validazione del TUMI. Se vuoi, conserva il codice anonimo per eventuali follow-up futuri.</p></div>","pages":[{"name":"consent","title":"Informativa e consenso al trattamento dei dati","elements":[{"type":"html","name":"consent_html","html":"\n<div style=\"background:#FFFFFF;padding:18px 22px;border-radius:10px;margin:4px 0 16px;box-shadow:0 1px 4px rgba(0,0,0,.06); line-height:1.55; color:#1b2528;\">\n  <h3 style=\"margin:0 0 12px;color:#05abc4;\">Informativa e consenso</h3>\n  <p><strong>Studio:</strong> Validazione internazionale del TUMI (Tabletop User Motivation Inventory).</p>\n  <p><strong>Promosso da:</strong> NexLudica APS — <a href=\"https://nexludica.org\" style=\"color:#05abc4;\">nexludica.org</a></p>\n  <p><strong>Responsabile della ricerca:</strong> Vittorio Guerrieri (<a href=\"mailto:vittorio.guerrieri@nexludica.org\" style=\"color:#05abc4;\">vittorio.guerrieri@nexludica.org</a>)</p>\n  <h4 style=\"margin:16px 0 6px;color:#1b2528;\">Scopo</h4>\n  <p>Validare uno strumento psicometrico che misura le motivazioni delle persone che giocano ai giochi da tavolo (TUMI). I risultati contribuiranno alla letteratura scientifica sul board gaming.</p>\n  <h4 style=\"margin:16px 0 6px;color:#1b2528;\">Cosa ti chiediamo</h4>\n  <p>Compilare un questionario di circa 20-25 minuti, suddiviso in 6 sezioni di affermazioni. Per ciascuna affermazione indicherai quanto sei d''accordo su una scala 1-7. Non ci sono risposte giuste o sbagliate, ad eccezione di una manciata di item di controllo della disattenzione (fattualmente impossibili o ovvi) inseriti in modo trasparente nella letteratura metodologica — Curran &amp; Hauser, 2019. Le affermazioni sono in inglese perché lo strumento è in fase di validazione internazionale.</p>\n  <h4 style=\"margin:16px 0 6px;color:#1b2528;\">Trattamento dei dati</h4>\n  <ul style=\"margin:6px 0 6px 22px; padding:0;\">\n    <li>Le risposte sono <strong>anonime</strong>: non raccogliamo nome, email, indirizzo IP identificabile (solo un hash anti-spam).</li>\n    <li>Crei tu stesso un <strong>codice anonimo</strong> rispondendo a 4 domande, in modo da consentirti — se vorrai — di partecipare a un follow-up futuro senza identificarti.</li>\n    <li>Memorizziamo l''<strong>ordine di somministrazione</strong> degli item (tramite un seed deterministico univoco per la tua sessione) per consentire analisi metodologiche.</li>\n    <li>I dati aggregati saranno usati per analisi psicometriche e potranno essere pubblicati in riviste scientifiche, sempre in forma aggregata.</li>\n    <li>Conservazione: i dati restano sui server di NexLudica APS (UE) per il tempo necessario alla ricerca, poi sono anonimizzati permanentemente o cancellati.</li>\n    <li>Base giuridica: art. 6.1.a GDPR (consenso) e art. 89 GDPR (finalità di ricerca scientifica).</li>\n  </ul>\n  <h4 style=\"margin:16px 0 6px;color:#1b2528;\">Diritti</h4>\n  <p>Puoi interrompere il questionario in qualsiasi momento senza dover dare spiegazioni. Per esercitare i diritti previsti dal GDPR (accesso, cancellazione, ecc.) scrivi al responsabile della ricerca all''indirizzo sopra indicato, fornendo il codice anonimo che genererai nelle prossime pagine.</p>\n  <h4 style=\"margin:16px 0 6px;color:#1b2528;\">Conferma</h4>\n  <p>Per partecipare devi avere almeno 18 anni. Procedendo confermi di aver letto l''informativa e di prestare consenso al trattamento dei dati per le finalità di ricerca descritte. <strong>Senza il consenso esplicito ai due punti sotto non potrai procedere</strong>.</p>\n</div>"},{"type":"boolean","name":"consent_age","title":"Confermo di avere almeno 18 anni","isRequired":true,"labelTrue":"Sì","labelFalse":"No","validators":[{"type":"expression","expression":"{consent_age} = true","text":"Per partecipare devi avere almeno 18 anni."}]},{"type":"boolean","name":"consent_data","title":"Ho letto l''informativa e presto consenso al trattamento dei dati per le finalità di ricerca descritte","isRequired":true,"labelTrue":"Sì","labelFalse":"No","validators":[{"type":"expression","expression":"{consent_data} = true","text":"Il consenso è necessario per procedere."}]}]},{"name":"codice_anonimo","title":"Codice anonimo","description":"Per collegare le tue risposte a eventuali questionari futuri senza identificarti, crea un codice personale rispondendo a queste 4 domande. Ricorda le risposte: ti serviranno per rigenerare lo stesso codice in futuro.","elements":[{"type":"text","name":"anon_madre","title":"Prima lettera del nome di tua madre","description":"Esempio: se tua madre si chiama Maria, scrivi M","isRequired":true,"maxLength":1,"validators":[{"type":"regex","regexp":"^[a-zA-Z\\u00C0-\\u017F]$","text":"Inserisci una sola lettera"}]},{"type":"text","name":"anon_giorno","title":"Giorno del tuo compleanno (1-31)","description":"Solo il giorno. Esempio: se sei nato/a il 15 marzo, scrivi 15","isRequired":true,"inputType":"number","min":1,"max":31,"validators":[{"type":"regex","regexp":"^([1-9]|[12][0-9]|3[01])$","text":"Inserisci un numero da 1 a 31"}]},{"type":"text","name":"anon_nome","title":"Prima lettera del tuo nome","description":"Esempio: se ti chiami Vittorio, scrivi V","isRequired":true,"maxLength":1,"validators":[{"type":"regex","regexp":"^[a-zA-Z\\u00C0-\\u017F]$","text":"Inserisci una sola lettera"}]},{"type":"text","name":"anon_telefono","title":"Prime due cifre del tuo numero di telefono","description":"Esempio: se il tuo numero inizia con 34..., scrivi 34","isRequired":true,"inputType":"number","min":0,"max":99,"validators":[{"type":"regex","regexp":"^[0-9]{1,2}$","text":"Inserisci due cifre (00-99)"}]}]},{"name":"demographics","title":"Informazioni sul rispondente","description":"Alcune informazioni di base per analizzare le risposte. Tutte le domande sono anonime.","elements":[{"type":"text","name":"age","title":"Età","isRequired":true,"inputType":"number","min":18,"max":99},{"type":"radiogroup","name":"gender","title":"Genere","isRequired":true,"choices":[{"value":"f","text":"Femminile"},{"value":"m","text":"Maschile"},{"value":"nb","text":"Non binario / altro"},{"value":"na","text":"Preferisco non rispondere"}]},{"type":"text","name":"country","title":"Paese di residenza","isRequired":true,"placeholder":"Es. Italia, USA, …"},{"type":"radiogroup","name":"years_playing","title":"Da quanti anni giochi a giochi da tavolo (moderni o classici)?","isRequired":true,"choices":[{"value":"lt1","text":"Meno di 1 anno"},{"value":"1to3","text":"1–3 anni"},{"value":"3to10","text":"3–10 anni"},{"value":"gt10","text":"Più di 10 anni"}]},{"type":"radiogroup","name":"play_frequency","title":"Con che frequenza giochi?","isRequired":true,"choices":[{"value":"rare","text":"Raramente (qualche volta l''anno)"},{"value":"monthly","text":"Una o due volte al mese"},{"value":"weekly","text":"Una o due volte alla settimana"},{"value":"daily","text":"Quasi tutti i giorni"}]},{"type":"rating","name":"expertise","title":"Come valuti la tua esperienza con i giochi da tavolo?","isRequired":true,"rateMin":1,"rateMax":5,"minRateDescription":"Principiante","maxRateDescription":"Esperto/a"}]},{"name":"tumi_1","title":"Sezione 1 di 6","description":"Le prossime sezioni contengono affermazioni sui giochi da tavolo. Per ciascuna, indica quanto sei d''accordo su una scala 1-7. Le affermazioni sono in inglese. L''ordine è randomizzato per la tua sessione.","elements":[{"type":"matrix","name":"tumi_matrix_1","title":"Per ciascuna affermazione indica quanto sei d''accordo (1 = strongly disagree, 7 = strongly agree)","isAllRowRequired":false,"columns":[{"value":1,"text":"1 — Strongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4 — Neutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7 — Strongly agree"}],"rows":[{"value":"CO04","text":"I track my win rates and strive to improve them."},{"value":"SO14","text":"Small talk during games distracts me more than it entertains."},{"value":"ID12","text":"I like it when I have the freedom to invent a story within a game"},{"value":"MA11","text":"I find it very rewarding to improve at a board game"},{"value":"PO09","text":"I like to collect games"},{"value":"SO05","text":"I like teaching board games"},{"value":"CO09","text":"I feel uncomfortable when games become too competitive."},{"value":"FO10","text":"Seeing other people talk about a game I don''t know makes me want to try it."},{"value":"FA15","text":"Stories in board games are just getting in the way"},{"value":"ID11","text":"I like games that allow me to tell my story"},{"value":"PR14","text":"It embarrasses me to point out that I get bored at a board game"},{"value":"ES10","text":"I like playing board games because they allow me to escape from real life."},{"value":"ES07","text":"I play games for entertainment rather than emotional relief."},{"value":"CU04","text":"I like building board game accessories"},{"value":"AE04","text":"The material of the game components is irrelevant"},{"value":"NO10","text":"I don''t have any game a play often because I find them comforting"},{"value":"AN01","text":"I’d miss the clatter of dice and shuffling if everything were digital."},{"value":"PR12","text":"If I don''t play certain games it would be hard for me to keep some friendships"},{"value":"SM05","text":"I avoid games that hinge on bluffing"},{"value":"AR08","text":"I dislike games with time pressure."},{"value":"NO09","text":"Replaying certain games gives me comfort"},{"value":"SO02","text":"I like to chat with other players"},{"value":"BG02","text":"I have never used a computer."},{"value":"PR02","text":"I play so as not to risk being excluded from my group of friends"},{"value":"RE04","text":"I see game nights as opportunities to strengthen relationships."},{"value":"CO18","text":"I like to beat others"},{"value":"AN06","text":"The physical bits don’t add much; the rules are what matter."},{"value":"MA14","text":"I like it if a game realistically simulates a fact of reality"},{"value":"TE09","text":"I find coordinating with others more frustrating than fun."},{"value":"PO15","text":"I want to own as many games as possible so I can play in more situations."},{"value":"SM09","text":"I like games where deals decide the outcome."},{"value":"BG06","text":"Oranges are fruit."},{"value":"GD11","text":"I evaluate how component design supports smooth play."},{"value":"SM14","text":"I like it when there are secrets among players"},{"value":"FA03","text":"I like to customize my character if the game allows it"},{"value":"FA16","text":"I like that the game world is detailed"},{"value":"SO13","text":"I prefer focused, quiet tables with minimal side chatter."},{"value":"FO02","text":"Limited editions tempt me even when I don’t need them."},{"value":"FO04","text":"New releases come and go; I barely notice."},{"value":"PR07","text":"If I don’t want to play, I simply don’t—no guilt attached."},{"value":"PR06","text":"I worry about being excluded if I don''t join gaming sessions."},{"value":"CO13","text":"Losing a game always makes me upset"},{"value":"FO11","text":"If there''s a lot of talk about a board game, it makes me want to try it."}]}]},{"name":"tumi_2","title":"Sezione 2 di 6","description":"Continua a indicare quanto sei d''accordo con ciascuna affermazione.","elements":[{"type":"matrix","name":"tumi_matrix_2","title":"Per ciascuna affermazione indica quanto sei d''accordo (1 = strongly disagree, 7 = strongly agree)","isAllRowRequired":false,"columns":[{"value":1,"text":"1 — Strongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4 — Neutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7 — Strongly agree"}],"rows":[{"value":"FO08","text":"I worry about missing out on limited or exclusive editions."},{"value":"ID05","text":"I usually just play as “myself,” not as a character"},{"value":"AR09","text":"I seek out games that create tension and suspense."},{"value":"SO04","text":"I often frequent environments where board games are played."},{"value":"FO03","text":"I need to play the latest games to stay current."},{"value":"SO15","text":"I find excessive table talk distracting."},{"value":"PR10","text":"It often happens that I play because my friends ask me to."},{"value":"AR04","text":"I find that playing board games increases my adrenaline"},{"value":"GD13","text":"The design behind a board game matters little to me."},{"value":"SM10","text":"Outmaneuvering people through negotiation is fun for me."},{"value":"PO03","text":"I like to look for good deals regarding board games."},{"value":"ID04","text":"I find myself speaking in character during role-playing games."},{"value":"ES15","text":"I use gaming to relax after a stressful day."},{"value":"RE06","text":"I keep my gaming life separate from my personal relationships."},{"value":"FO09","text":"I feel anxious when I hear about popular games I haven''t tried."},{"value":"GD05","text":"I like to discuss design choices of games"},{"value":"MA12","text":"I feel proud when I master an aspect of a board game"},{"value":"AR11","text":"I like the excitement of not knowing what is about to happen."},{"value":"AE03","text":"I appreciate the tactile pleasure of high-quality game pieces."},{"value":"CU06","text":"I enjoy making games uniquely mine through modifications."},{"value":"CO02","text":"I play games with the primary goal of winning."},{"value":"CO15","text":"I like to be known as someone good at certain games"},{"value":"PO01","text":"I like acquiring titles even if I’m not sure when I’ll play them."},{"value":"SM06","text":"I like games where deception decide the outcome"},{"value":"CO07","text":"I don''t mind losing as long as everyone has fun."},{"value":"AE09","text":"Artwork is irrelevant to me; function is all that matters."},{"value":"PR13","text":"Sometimes I happen to play even if I don''t feel like it."},{"value":"RE12","text":"I want to form meaningful friendships with the people I play board games with."},{"value":"BG01","text":"I work fourteen months in a year."},{"value":"NO11","text":"Some games I like because an important person in my life taught them to me"},{"value":"RE07","text":"I don''t expect games to affect my friendships."},{"value":"ID10","text":"If I don''t identify with a character, I don''t have fun."},{"value":"GD02","text":"I like to \"break\" the games rules"},{"value":"CU10","text":"I find painting miniatures to be boring."},{"value":"ID07","text":"I avoid roleplay"},{"value":"RE05","text":"Once the game ends, I’m not looking to connect further."},{"value":"GD04","text":"I don''t like to explore different ways to bend the rules"},{"value":"MA01","text":"I like drilling into game systems until I truly understand them."},{"value":"SO16","text":"I would enjoy games just as much played in silence."},{"value":"PR03","text":"I sometimes join games mainly because others expect me to."},{"value":"MA20","text":"I get frustrated when randomness removes my ability to plan."},{"value":"PO16","text":"I like owning the right game for every situation"},{"value":"TE02","text":"It''s also important for me to be able to support other players."}]}]},{"name":"tumi_3","title":"Sezione 3 di 6","description":"Continua a indicare quanto sei d''accordo con ciascuna affermazione.","elements":[{"type":"matrix","name":"tumi_matrix_3","title":"Per ciascuna affermazione indica quanto sei d''accordo (1 = strongly disagree, 7 = strongly agree)","isAllRowRequired":false,"columns":[{"value":1,"text":"1 — Strongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4 — Neutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7 — Strongly agree"}],"rows":[{"value":"PO12","text":"I see no value in owning games I rarely play."},{"value":"FA09","text":"I follow the plot as if I’m living inside it."},{"value":"PO13","text":"A big collection doesn’t interest me; access is enough."},{"value":"ES14","text":"When I play, I lose track of time."},{"value":"PO06","text":"I sometimes avoid bringing around certain games I really care about"},{"value":"FA14","text":"Board game stories are important to me"},{"value":"ES02","text":"Playing helps me switch off worries I can’t shake otherwise."},{"value":"MA18","text":"I like to improve as a player over time"},{"value":"ES04","text":"I find games help me manage difficult emotions."},{"value":"SM11","text":"I dislike having to make deals during a game"},{"value":"ES05","text":"I rarely play to distract myself from how I’m feeling."},{"value":"CO05","text":"I don''t surrender easily"},{"value":"SM08","text":"I prefer games where all information is open and honest."},{"value":"CU09","text":"I stick to official pieces without changes."},{"value":"MA07","text":"I’m fine playing sloppily if it keeps things moving."},{"value":"MA17","text":"I like games with great strategic depth"},{"value":"FO05","text":"I''m content playing old games."},{"value":"TE03","text":"I like to help other players"},{"value":"CO17","text":"The most fun part is the head-to-head comparison with opponents."},{"value":"CU02","text":"I like to improve the pieces of my board games"},{"value":"NO04","text":"I don’t cling to “classics” just because they’re classics."},{"value":"CU11","text":"I like game that involve crafting something new"},{"value":"ES11","text":"I like to imagine a better version of my life in board games"},{"value":"CO19","text":"I like to do better than other players"},{"value":"AE10","text":"I find elaborate game art to be an unnecessary expense."},{"value":"RE02","text":"I like lasting friendships through gaming groups."},{"value":"CO01","text":"Outplaying others gives me a real thrill."},{"value":"AN03","text":"I’d be just as happy playing a digital version of most games."},{"value":"AN04","text":"Physical stuff in games don’t affect my enjoyment."},{"value":"NO08","text":"I don''t like to play traditional games"},{"value":"NO02","text":"Familiar titles comfort me because of old memories."},{"value":"RE01","text":"I use game nights to deepen friendships outside the game."},{"value":"AE05","text":"I''m drawn to games with beautiful artwork and components."},{"value":"SO09","text":"Table talk and jokes are a big part of why I play."},{"value":"CO03","text":"I study rules to win more often"},{"value":"NO03","text":"My past gaming history has little to do with what I play now."},{"value":"PO05","text":"I don''t care if my games get worn out with use"},{"value":"SM01","text":"I don''t enjoy games where I have to ally myself with other players"},{"value":"AN07","text":"The tactile feel of cards, dice, and miniatures is a big draw for me."},{"value":"CU03","text":"I like board games that involve customization, such as painting miniatures."},{"value":"AN02","text":"I find digital implementations lose something essential."},{"value":"BG03","text":"I am paid biweekly by leprechauns."},{"value":"RE10","text":"I like it if my board game friends offer me support when I have a real-life problem"}]}]},{"name":"tumi_4","title":"Sezione 4 di 6","description":"Continua a indicare quanto sei d''accordo con ciascuna affermazione.","elements":[{"type":"matrix","name":"tumi_matrix_4","title":"Per ciascuna affermazione indica quanto sei d''accordo (1 = strongly disagree, 7 = strongly agree)","isAllRowRequired":false,"columns":[{"value":1,"text":"1 — Strongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4 — Neutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7 — Strongly agree"}],"rows":[{"value":"ID02","text":"I dedicate a lot of care to character creation, when the game allows it."},{"value":"FA05","text":"Getting lost in a game’s story is an important part for me."},{"value":"MA06","text":"I prefer simple games that don''t require complex thinking"},{"value":"TE01","text":"I prefer to play in a team rather than alone"},{"value":"ID03","text":"I enjoy making decisions as if I were actually my character."},{"value":"PR05","text":"I sometimes keep playing a campaign because quitting would feel rude."},{"value":"CU05","text":"Painting minis or customising components is part of the fun for me."},{"value":"AR02","text":"I enjoy the adrenaline rush of high-stakes moments."},{"value":"TE10","text":"Group strategy talk feels like a chore, not a perk."},{"value":"ES01","text":"I use gaming sessions to decompress from daily stress."},{"value":"MA03","text":"I feel satisfied when I fully understand a game''s systems."},{"value":"FO07","text":"I ignore gaming trends and hype."},{"value":"MA05","text":"Learning every nuance of a game feels like overkill to me."},{"value":"MA08","text":"Deep strategy talk bores me quickly."},{"value":"CO12","text":"Losing is not fun"},{"value":"MA02","text":"I enjoy discovering optimal strategies"},{"value":"RE08","text":"I would play just as happily with people I will never meet again"},{"value":"SO11","text":"I like games that encourage table talk and interaction."},{"value":"FO01","text":"I feel the urge to try the latest hot release right away."},{"value":"ES16","text":"Playing improves my mood when I feel down."},{"value":"FA12","text":"I skip through story elements to get to the gameplay."},{"value":"SM02","text":"I like it when alliances are formed between players"},{"value":"CO10","text":"Competing against others feels more stressful than fun."},{"value":"ID08","text":"I like games where I can play a character."},{"value":"FA10","text":"I find myself thinking about game narratives long after playing."},{"value":"PO14","text":"Playing a game I own is more satisfying than playing a borrowed one."},{"value":"ES03","text":"I use long sessions when I need a mental break from my problems"},{"value":"CU01","text":"I like to embellish my board games"},{"value":"TE04","text":"I like to play board games collaboratively"},{"value":"ES12","text":"When I play board games, I think less about my problems."},{"value":"CU08","text":"I see no point in customizing game components."},{"value":"AR03","text":"I play board games because they excite me"},{"value":"SM03","text":"I find games with betrayal exciting."},{"value":"FA02","text":"I look forward to finding out what''s going to happen in the story of a board game."},{"value":"NO06","text":"I play some games because they remind me of happy moments from my past"},{"value":"ES09","text":"I like playing board games because they allow me to distract myself from my problems"},{"value":"RE09","text":"I enjoy talking about my personal problems with my board game companions."},{"value":"SO08","text":"Playing board games is part of a routine with my friends"},{"value":"NO07","text":"Playing certain games is a beautiful tradition"},{"value":"PO02","text":"Buying games I won’t use feels pointless to me."},{"value":"FA08","text":"I like to \"lose myself\" in a story while playing."},{"value":"SO06","text":"I like games because they make social interactions more pleasant"},{"value":"RE11","text":"I enjoy having important and deep conversations with other players."}]}]},{"name":"tumi_5","title":"Sezione 5 di 6","description":"Continua a indicare quanto sei d''accordo con ciascuna affermazione.","elements":[{"type":"matrix","name":"tumi_matrix_5","title":"Per ciascuna affermazione indica quanto sei d''accordo (1 = strongly disagree, 7 = strongly agree)","isAllRowRequired":false,"columns":[{"value":1,"text":"1 — Strongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4 — Neutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7 — Strongly agree"}],"rows":[{"value":"CO20","text":"Being in a ranking motivates me to play"},{"value":"AE08","text":"Fancy visuals don’t affect whether I like a game."},{"value":"SO12","text":"I like sessions where conversation flows constantly."},{"value":"NO05","text":"I prefer discovering new games over revisiting old ones."},{"value":"MA16","text":"I like simple games"},{"value":"CO06","text":"I shy away from direct competition"},{"value":"MA19","text":"I like finding clever solutions to problems"},{"value":"MA13","text":"I like understanding complex mechanics"},{"value":"RE03","text":"I’m happy when a session leads to plans or chats afterward."},{"value":"GD06","text":"I enjoy thinking about how a board game’s mechanics shape player decisions."},{"value":"MA10","text":"I like to think of all possible strategies when I play board games."},{"value":"SO10","text":"I enjoy playful banter even when it’s not about the game."},{"value":"GD12","text":"I rarely think about why a board game works; I just play."},{"value":"FA06","text":"I like to do things I couldn''t do in real life through board games"},{"value":"AE06","text":"Gorgeous components can win me over even before I know the rules."},{"value":"ES06","text":"I feel like playing games only when I''m mentally in a good place"},{"value":"BG04","text":"I have been to every country in the world."},{"value":"SM04","text":"I enjoy bluffing games."},{"value":"SO07","text":"I like to have shared experiences playing that I can talk about later."},{"value":"AR05","text":"Playing board games gives me a lot of energy"},{"value":"FO06","text":"I don''t care if I miss out on new releases."},{"value":"AN11","text":"I like the digital versions of the board game"},{"value":"AE02","text":"I barely notice component quality once we start playing."},{"value":"PR01","text":"I don''t need to play games to keep my friendships"},{"value":"ID06","text":"Adopting a character’s viewpoint feels forced to me."},{"value":"AR01","text":"My heart rate jumps in suspenseful turns—and I love it."},{"value":"AN10","text":"I like that board games are played in person"},{"value":"NO01","text":"I keep playing games that hold special memories for me."},{"value":"PR09","text":"I never feel pressured to participate in games."},{"value":"PR08","text":"Group pressure doesn’t influence my decision to join."},{"value":"MA15","text":"I like it if I have to think a lot about the strategies to put into a game"},{"value":"CO16","text":"I like to play to show my friends how good I am"},{"value":"ES13","text":"When I play board games, I experience fewer negative emotions"},{"value":"CO08","text":"I don’t chase optimal moves; I just go with the flow."},{"value":"AR06","text":"I prefer calm, relaxing games without pressure."},{"value":"PO10","text":"Adding a new game to my library excites me"},{"value":"MA09","text":"I like to understand all aspects of a board game I''m playing"},{"value":"PO07","text":"Owning shelves of games is rewarding in itself."},{"value":"AR10","text":"Board games keep me on the edge of my seat"},{"value":"FA11","text":"Without a rich narrative, a game feels thin to me."},{"value":"ES18","text":"I like feeling in control while playing"},{"value":"SM12","text":"I like games where you have to negotiate with other players"},{"value":"PO11","text":"I don’t care who owns the game as long as I can play."}]}]},{"name":"tumi_6","title":"Sezione 6 di 6","description":"Continua a indicare quanto sei d''accordo con ciascuna affermazione.","elements":[{"type":"matrix","name":"tumi_matrix_6","title":"Per ciascuna affermazione indica quanto sei d''accordo (1 = strongly disagree, 7 = strongly agree)","isAllRowRequired":false,"columns":[{"value":1,"text":"1 — Strongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4 — Neutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7 — Strongly agree"}],"rows":[{"value":"AE07","text":"Visual appeal is an important part of why I choose to play games"},{"value":"SM13","text":"I find games with secret roles exciting."},{"value":"SO03","text":"The atmosphere created among the players is important to me."},{"value":"MA04","text":"I enjoy optimizing turns even when no one else is watching."},{"value":"GD09","text":"I often propose house rules to test alternative design ideas."},{"value":"TE06","text":"Cooperative victories feel better than solo wins."},{"value":"ES08","text":"When I''m stressed out, I''m not in the mood for playing"},{"value":"NO12","text":"Who teaches me a game is irrelevant to the attachement I have to the game"},{"value":"SO01","text":"I like meeting other players"},{"value":"AN05","text":"I prefer digital games for their convenience and automation."},{"value":"AN09","text":"I experience board games as a break from screens"},{"value":"GD07","text":"I pay attention to how small rule changes could improve a board game."},{"value":"GD03","text":"I like to push the rules of a game to the limit"},{"value":"PO04","text":"I am careful not to ruin my games."},{"value":"AE01","text":"The color, shape, and feel of board game pieces are important to me"},{"value":"PR04","text":"I sometimes play games to avoid disappointing others."},{"value":"PR11","text":"I don''t want to disappoint people who expect me to play."},{"value":"FA07","text":"I like the thrill of taking on an alter ego in a game"},{"value":"SM07","text":"I dislike games that require lying or deceiving others."},{"value":"TE05","text":"Coordinating with others toward a joint win is satisfying."},{"value":"FA04","text":"I like when I can develop my character in the games"},{"value":"AN08","text":"Handling physical components makes the experience real for me."},{"value":"TE07","text":"I enjoy synchronizing actions with others."},{"value":"CO14","text":"For me, it''s important to be the best person at playing."},{"value":"ES17","text":"Playing improves my mood"},{"value":"GD14","text":"I am not interested in how rules work during play."},{"value":"GD01","text":"I like to discover new and inventive game designs"},{"value":"TE08","text":"I prefer having complete responsability over my own success."},{"value":"CU07","text":"I take pride in personalizing my gaming accessories."},{"value":"GD10","text":"The fit between theme and mechanics is a major reason I want to play a board game."},{"value":"AR07","text":"I avoid games that make me feel anxious or stressed."},{"value":"FA13","text":"I don’t need lore or worldbuilding to enjoy a session"},{"value":"PO08","text":"I take pride in my game collection''s size and variety."},{"value":"CO11","text":"Winning is important to me"},{"value":"ID09","text":"I like the thrill of pretending to be someone else"},{"value":"ID01","text":"I like exploring how my character would think and feel."},{"value":"BG05","text":"I have the power to cast spells on others."},{"value":"FA01","text":"Narrative twists rarely grab my attention."},{"value":"GD08","text":"Understanding the balance between luck and skill in a design motivates me to play."}]}]}]}',
  0,
  'active',
  3,
  unixepoch()*1000,
  unixepoch()*1000
);
